import React from "react";
import { useCart } from "react-use-cart";
import toast from "react-hot-toast";
import Header from "../Home/Header";
import Topbar from "../Home/Topbar"

export default function Cart() {
  const {
    items,
    updateItemQuantity,
    removeItem,
    cartTotal,
    totalItems,
    isEmpty,
  } = useCart();

  const phoneNumber = "201234567890"; 

  if (isEmpty) {
    return (
      <div>
      <Topbar />
       <Header/>
<br/><br/><br/>
        <h2
          style={{
            textAlign: "center",
            marginTop: "120px",
            color: "#fff",
          }}
        >
          🛒 Your cart is empty
        </h2>
      </div>
    );
  }

  return (
    <div>
      <Topbar/>
      <Header />
<br/><br/><br/><br/><br/><br/>
      <section className="section service bg-black-10" aria-label="cart">
        <div className="container">

          <h2 className="headline-1 section-title text-center mb-5">
            Your Cart ({totalItems})
          </h2>

          {/* المنتجات */}
          <ul className="grid-list">
            {items.map((item) => (
              <li key={item.id}>
                <div className="service-card has-before hover:shine">

                  {/* صورة المنتج */}
                  <figure
                    className="card-banner img-holder"
                    style={{ "--width": 285, "--height": 200 }}
                  >
                    <img style={{borderRadius:"20px"}}
                      src={item.image}
                      alt={item.name}
                      className="img-cover"
                      loading="lazy"
                    />
                  </figure>

                  {/* محتوى الكرت */}
                  <div className="card-content text-center">
                    <h3 className="title-4 card-title">
                      {item.name}
                    </h3>

                    <p className="label-2 mb-1">
                      Price: ${item.price}
                    </p>

                    {/* التحكم بالكمية */}
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                        gap: "12px",
                        margin: "12px 0",
                      }}
                    >
                      <button
                        className="btn-text"
                        onClick={() => {
                          if (item.quantity === 1) return;
                          updateItemQuantity(item.id, item.quantity - 1);
                        }}
                      >
                        −
                      </button>

                      <span className="label-2">
                        {item.quantity}
                      </span>

                      <button
                        className="btn-text"
                        onClick={() =>
                          updateItemQuantity(item.id, item.quantity + 1)
                        }
                      >
                        +
                      </button>
                    </div>

                    <p className="label-2 mb-2">
                      Total: ${item.price * item.quantity}
                    </p>

                    {/* حذف */}
                    <button
                      onClick={() => {
                        removeItem(item.id);
                        toast.error("Item removed");
                      }}
                      className="btn-text hover-underline label-2"
                      style={{ color: "#ff6b6b" }}
                    >
                      Remove
                    </button>
                  </div>
                </div>
              </li>
            ))}
          </ul>

          {/* الإجمالي + Checkout */}
          <div
            style={{
              marginTop: "60px",
              textAlign: "center",
            }}
          >
            <h3 className="headline-2">
              Cart Total: ${cartTotal}
            </h3>

            <button
              className="btn btn-secondary whatsApp"
              style={{ marginTop: "20px",display:"flex",justifyContent:"center",alignItems:"center"}}
              onClick={() => {
                const message = items
                  .map(
                    (item) =>
                      `🍽 ${item.name} x${item.quantity} = $${item.price * item.quantity}`
                  )
                  .join("%0A");

                const total = `%0A%0ATotal: $${cartTotal}`;

                window.open(
                  `https://wa.me/${phoneNumber}?text=${message}${total}`,
                  "_blank"
                );
              }}
            >
              <ion-icon
                name="logo-whatsapp"
                style={{ marginRight: "8px", fontSize: "20px" }}
              ></ion-icon>
              Checkout via WhatsApp
            </button>
          </div>

        </div>
      </section>
    </div>
  );
}
