import React, { useContext, useState } from "react";
import { Link } from "react-router-dom";
import { useCart } from "react-use-cart";
import Header from "../Home/Header";
import Topbar from "../Home/Topbar"
import { apivalue } from "../data/AllData";
import { useFavorites } from "../Favorites/FavoritesContext";

export default function Menus() {
  const data = useContext(apivalue);
  const { addItem } = useCart();
  const { toggleFavorite, isFavorite } = useFavorites();

  const [search, setSearch] = useState("");
  const [toast, setToast] = useState("");
  const [animatedId, setAnimatedId] = useState(null);

  const filteredData = data.filter(
    (item) => item.strMeal.toLowerCase().includes(search.toLowerCase()) || item.idMeal.toString().includes(search)
  );

  return (
    <div>
      <Topbar/>
      <Header />
      <br/>  <br/>  <br/>  <br/>

      <section className="section service bg-black-10 text-center">
        <div className="container">
          <p className="section-subtitle label-2">Delicious Meals</p>
          <h2 className="headline-1 section-title">Explore Our Menus</h2>

          <div style={{ maxWidth: "400px", margin: "0 auto 40px" }}>
            <input
              type="text"
              placeholder="Search by name or ID..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              style={{ backgroundColor: "#fff", padding: "12px 15px", borderRadius: "8px", border: "1px solid #ccc", width: "100%" }}
            />
          </div>

          <ul className="grid-list">
            {filteredData.map((item) => (
              <li key={item.idMeal}>
                <div className="service-card has-before hover:shine" style={{ position: "relative" }}>

                  <button
                    onClick={() => {
                      toggleFavorite(item);
                      setAnimatedId(item.idMeal);
                      setToast(isFavorite(item.idMeal) ? "💔 تمت الإزالة من المفضلة" : "❤️ تمت الإضافة للمفضلة");
                      setTimeout(() => { setAnimatedId(null); setToast(""); }, 2000);
                    }}
                    style={{ position: "absolute", top: "15px", right: "15px", background: "transparent", border: "none", cursor: "pointer", zIndex: 10 }}
                  >
                    <ion-icon
                      name={isFavorite(item.idMeal) ? "heart" : "heart-outline"}
                      className={animatedId === item.idMeal ? "heart-animate" : ""}
                      style={{ fontSize: "24px", color: isFavorite(item.idMeal) ? "red" : "#fff" }}
                    ></ion-icon>
                  </button>

                  <figure className="card-banner img-holder">
                    <img src={item.strMealThumb} alt={item.strMeal} className="img-cover" />
                  </figure>

                  <div className="card-content">
                    <h3 className="title-4 card-title">{item.strMeal}</h3>
                    <p style={{fontSize:"18px"}} className="label-2 mb-2">Category: {item.strCategory}</p>
                    <p style={{fontSize:"18px"}} className="label-2 mb-2">Area: {item.strArea}</p>

                    <div style={{ display: "flex", justifyContent: "space-between", marginTop: "15px" }}>
                      <Link to={`/singleMenus/${item.idMeal}`} className="btn-text">View Details</Link>

                      <button  style={{fontSize:"22px"}}
                        className="btn-text"
                        onClick={() => addItem({ id: item.idMeal, name: item.strMeal, price: 15, image: item.strMealThumb })}
                      >
                        <ion-icon name="cart-outline"></ion-icon>
                      </button>
                      
                    </div>
                    <br/>  <br/>
                  </div>
                </div>
              </li>
            ))}
          </ul>

          {toast && <div className="toast">{toast}</div>}
        </div>
      </section>
 
    </div>
  );
}
