import React, { useContext, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { apivalue } from "../data/AllData"; 
import Header from "../Home/Header";
import Topbar from "../Home/Topbar";
import { useCart } from "react-use-cart";
import { useFavorites } from "../Favorites/FavoritesContext";

export default function SingleMenus() {
  const { id } = useParams();
  const data = useContext(apivalue);
  const { addItem } = useCart();
  const { toggleFavorite, isFavorite } = useFavorites();

  const [animatedId, setAnimatedId] = useState(null);
  const [toast, setToast] = useState("");

  const product = data.find(
    (item) => item.idMeal === id || item.idMeal === Number(id)
  );

  const otherProducts = data
    .filter((item) => item.idMeal !== product?.idMeal)
    .slice(0, 3);

  return (
    <div>
      <Topbar/>
      <Header />
      <br /><br /><br /><br /><br /><br />

      <div
        className="container"
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          marginTop: "60px",
          marginBottom: "60px",
        }}
      >
        {product ? (
          <ul className="grid-list justify-content-center" style={{ width: "100%" }}>
            <li
              style={{
                width: "90%",
                maxWidth: "1000px",
                margin: "0 auto",
              }}
            >
              <div className="service-card has-before hover:shine" style={{ position: "relative" }}>
                
                {/* أيقونات المفضلة وعربة التسوق */}
                <div style={{ position: "absolute", top: "15px", right: "15px", display: "flex", gap: "10px", zIndex: 10 }}>
                  <button
                    onClick={() => {
                      toggleFavorite(product);
                      setAnimatedId(product.idMeal);
                      setToast(isFavorite(product.idMeal) ? "💔 تمت الإزالة من المفضلة" : "❤️ تمت الإضافة للمفضلة");
                      setTimeout(() => { setAnimatedId(null); setToast(""); }, 2000);
                    }}
                    style={{ background: "transparent", border: "none", cursor: "pointer" }}
                  >
                    <ion-icon
                      name={isFavorite(product.idMeal) ? "heart" : "heart-outline"}
                      className={animatedId === product.idMeal ? "heart-animate" : ""}
                      style={{ fontSize: "24px", color: isFavorite(product.idMeal) ? "red" : "#fff" }}
                    ></ion-icon>
                  </button>

                  <button
                    onClick={() => addItem({ id: product.idMeal, name: product.strMeal, price: 15, image: product.strMealThumb })}
                    style={{ background: "transparent", border: "none", cursor: "pointer" }}
                  >
                    <ion-icon name="cart-outline" style={{ fontSize: "24px", color: "#fff" }}></ion-icon>
                  </button>
                </div>

                <figure
                  className="card-banner img-holder"
                  style={{ "--width": 285, "--height": 336 }}
                >
                  <img style={{borderRadius:"20px"}}
                    src={product.strMealThumb}
                    alt={product.strMeal}
                    width="100%"
                    height="250"
                    className="img-cover"
                    loading="lazy"
                  />
                </figure>
                <br />

                <div className="card-content text-center">
                  <h3 className="title-4 card-title">{product.strMeal}</h3>
                  <p className="label-2 mb-2">Category: {product.strCategory}</p>
                  <p className="label-2 mb-2">Area: {product.strArea}</p>
                  <p className="label-2 mb-2">Instructions: {product.strInstructions}</p>

                  <ul className="list-unstyled text-start mt-3">
                    <li>ID: <span>{product.idMeal}</span></li>
                    {product.strTags && <li>Tags: <span>{product.strTags}</span></li>}
                  </ul>

                  <Link
                    to="/menus"
                    className="btn-text hover-underline label-2 mt-3"
                  >
                    Back to Menus
                  </Link>
                </div>
              </div>
            </li>
          </ul>
        ) : (
          <h4 className="text-center mt-5">Product not found 😢</h4>
        )}
      </div>

      {otherProducts.length > 0 && (
        <section className="section service bg-black-10 text-center">
          <div className="container">
            <h2 className="headline-1 section-title mb-4">You Might Also Like</h2>
            <ul className="grid-list">
              {otherProducts.map((item) => (
                <li key={item.idMeal}>
                  <div className="service-card has-before hover:shine" style={{ position: "relative" }}>
                    
                    {/* أيقونات المفضلة وعربة التسوق */}
                    <div style={{ position: "absolute", top: "15px", right: "15px", display: "flex", gap: "10px", zIndex: 10 }}>
                      <button
                        onClick={() => {
                          toggleFavorite(item);
                          setAnimatedId(item.idMeal);
                          setToast(isFavorite(item.idMeal) ? "💔 تمت الإزالة من المفضلة" : "❤️ تمت الإضافة للمفضلة");
                          setTimeout(() => { setAnimatedId(null); setToast(""); }, 2000);
                        }}
                        style={{ background: "transparent", border: "none", cursor: "pointer" }}
                      >
                        <ion-icon
                          name={isFavorite(item.idMeal) ? "heart" : "heart-outline"}
                          className={animatedId === item.idMeal ? "heart-animate" : ""}
                          style={{ fontSize: "24px", color: isFavorite(item.idMeal) ? "red" : "#fff" }}
                        ></ion-icon>
                      </button>

                      <button
                        onClick={() => addItem({ id: item.idMeal, name: item.strMeal, price: 15, image: item.strMealThumb })}
                        style={{ background: "transparent", border: "none", cursor: "pointer" }}
                      >
                        <ion-icon name="cart-outline" style={{ fontSize: "24px", color: "#fff" }}></ion-icon>
                      </button>
                    </div>

                    <figure className="card-banner img-holder" style={{ "--width": 285, "--height": 336 }}>
                      <img style={{borderRadius:"20px"}} src={item.strMealThumb} alt={item.strMeal} className="img-cover" />
                    </figure>

                    <div className="card-content">
                      <h3 className="title-4 card-title">{item.strMeal}</h3>
                      <p className="label-2 mb-2">Category: {item.strCategory}</p>
                      <p className="label-2 mb-2">Area: {item.strArea}</p>
                      <Link
                        to={`/singleMenus/${item.idMeal}`}
                        className="btn-text hover-underline label-2"
                      >
                        View Details
                      </Link>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        </section>
      )}

      {toast && <div className="toast">{toast}</div>}
    </div>
  );
}
