

import { useState } from "react";
import { Link } from "react-router";
import "./Login.css";
import Header from "../Home/Header";
import Topbar from "../Home/Topbar";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!email || !password) {
      setError("Please fill in all fields");
      return;
    }

    setError("");
    console.log({ email, password, rememberMe });
  };

  return (

 <div>
  <Topbar/>
  <Header />
  <br /><br /><br /><br /><br /><br /><br />

  <section id="login" className="login ">
    <div
      className="container"
      style={{ width: "50%", textAlign: "center", height: "300px" }}
    >
      <form
        className="form-left"
        onSubmit={handleSubmit}
        autoComplete="off"
      >
        <h2 className="headline-1 text-center">Login</h2>

        <p className="form-text text-center">
          Please login to your account
        </p>

        {error && (
          <p className="form-text text-center error-text">
            {error}
          </p>
        )}

        {/* Social Login */}
        <div
          className="input-wrapper social-wrapper"
          style={{ display: "flex", gap: "25px", textAlign: "center" }}
        >
          <button
            type="button"
            className="btn btn-secondary social-btn"
            style={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: "10px",
              fontSize:"30px"
            }}
          >
            <ion-icon name="logo-google"></ion-icon>
          </button>

          <button
            type="button"
            className="btn btn-secondary social-btn"
            style={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: "10px",
              fontSize:"30px"
            }}
          >
            <ion-icon name="logo-facebook"></ion-icon>
          </button>
        </div>

        <br />

        {/* OR */}
        <div className="or-divider">
          <span></span>
          <span>OR</span>
          <span></span>
        </div>

        <br />

        {/* Email */}
        <div className="input-wrapper">
          <div className="icon-wrapper">
            <ion-icon name="mail-outline"></ion-icon>
            <input
              type="email"
              className="input-field"
              placeholder="Email Address"
              autoComplete="off"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
        </div>

        {/* Password */}
        <div className="input-wrapper">
          <div className="icon-wrapper">
            <ion-icon name="lock-closed-outline"></ion-icon>
            <input
              type={showPassword ? "text" : "password"}
              className="input-field"
              placeholder="Password"
              autoComplete="off"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <ion-icon
              name={showPassword ? "eye-off-outline" : "eye-outline"}
              className="eye-icon"
              onClick={() => setShowPassword(!showPassword)}
            ></ion-icon>
          </div>
        </div>

        {/* Remember Me + Forgot */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div className="remember-row">
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={() => setRememberMe(!rememberMe)}
            />
            <label className="remember-label">
              Remember me
            </label>
          </div>

          <div>
            <Link to="/forgot-password" className="link">
              Forgot password?
            </Link>
          </div>
        </div>

        <br />

        {/* Submit */}
        <button type="submit" className="btn btn-secondary full-btn">
          Login
        </button>

        <p className="form-text text-center bottom-text">
          Don’t have an account?{" "}
          <Link to="/Register" className="link">
            Sign Up
          </Link>
        </p>
      </form>
    </div>
  </section>
</div>

  );
};

export default Login;
