// src/Home/Header.jsx
import { useState, useEffect, useContext } from "react";
import { Link } from "react-router-dom";
import { useCart } from "react-use-cart";
import { FavoritesContext, useFavorites } from "../Favorites/FavoritesContext"; 

export default function Header() {
  const [menuOpen, setMenuOpen] = useState(false);
  const { totalItems } = useCart();
  const { favorites } = useFavorites();
  const [animateFav, setAnimateFav] = useState(false);

         
  useEffect(() => {
    if (favorites.length > 0) {
      setAnimateFav(true);
      setTimeout(() => setAnimateFav(false), 300);
    }
  }, [favorites.length]);

  return (
    <header className="header" data-header="">
      <div className="container">

        {/* الشعار */}
        <Link to="/" className="logo">
          <img
            src="./assets/images/logo.svg"
            width={160}
            height={50}
            alt="Grilli - Home"
          />
        </Link>

        {/* Navbar */}
        <nav className={`navbar ${menuOpen ? "active" : ""}`} data-navbar="">
          {/*  إغلاق القائمة */}
          <button
            className="close-btn"
            aria-label="close menu"
            onClick={() => setMenuOpen(false)}
          >
            ✕
          </button>

          {/* شعار داخل القائمة */}
          <Link to="/" className="logo">
            <img
              src="./assets/images/logo.svg"
              width={160}
              height={50}
              alt="Grilli - Home"
            />
          </Link>

          <ul className="navbar-list">
            <li className="navbar-item">
              <Link
                to="/"
                className="navbar-link hover-underline"
                onClick={() => setMenuOpen(false)}
              >
                <div className="separator" />
                <span className="span">Home</span>
              </Link>
            </li>

            <li className="navbar-item">
              <Link
                to="/menus"
                className="navbar-link hover-underline"
                onClick={() => setMenuOpen(false)}
              >
                <div className="separator" />
                <span className="span">Menus</span>
              </Link>
            </li>

            <li className="navbar-item">
              <a href="#about" className="navbar-link hover-underline">
                <div className="separator" />
                <span className="span">About Us</span>
              </a>
            </li>

            <li className="navbar-item">
              <a href="#offer" className="navbar-link hover-underline">
                <div className="separator" />
                <span className="span">Offer</span>
              </a>
            </li>

            <li className="navbar-item">
              <Link
                to="/login"
                className="navbar-link hover-underline"
                onClick={() => setMenuOpen(false)}
              >
                <div className="separator" />
                <span className="span">Login</span>
              </Link>
            </li>

            {/* ❤️ المفضلة */}
            <li className="navbar-item" style={{ position: "relative" }}>
              <Link
                to="/favorites"
                className="navbar-link hover-underline"
                onClick={() => setMenuOpen(false)}
              >
                <ion-icon
                  name="heart"
                  style={{ fontSize: "22px", color: "red" }}
                />
                {favorites.length > 0 && (
                  <span
                    className={animateFav ? "counter-animate" : ""}
                    style={{
                      position: "absolute",
                      top: "-20px",
                      right: "-8px",
                      background: "black",
                      color: "#fff",
                      borderRadius: "50%",
                      padding: "2px 6px",
                      fontSize: "11px",
                      fontWeight: "bold",
                    }}
                  >
                    {favorites.length}
                  </span>
                )}
              </Link>
            </li>

            {/* Cart */}
            <li className="navbar-item" style={{ position: "relative" }}>
              <Link
                to="/cart"
                className="navbar-link hover-underline"
                onClick={() => setMenuOpen(false)}
              >
                <div className="separator" />
                <ion-icon
                  name="cart-outline"
                  style={{ fontSize: "28px", color: "#fcf8f8" }}
                />
                {totalItems > 0 && (
                  <span
                    style={{
                      position: "absolute",
                      top: "-6px",
                      right: "-10px",
                      background: "red",
                      color: "#fff",
                      borderRadius: "50%",
                      fontSize: "12px",
                      padding: "2px 6px",
                      lineHeight: "1",
                    }}
                  >
                    {totalItems}
                  </span>
                )}
              </Link>
            </li>
          </ul>
{/* معلومات الاتصال */}
          <div className="text-center">
            <p className="headline-1 navbar-title">Visit Us</p>
            <address className="body-4">
              Restaurant St, Delicious City, <br />
              London 9578, UK
            </address>
            <p className="body-4 navbar-text">Open: 9.30 am - 2.30pm</p>
            <a href="mailto:booking@grilli.com" className="body-4 sidebar-link">
              booking@grilli.com
            </a>
          </div>
        </nav>

        {/* Find A Table */}
        <a href="#reserv" className="btn btn-secondary">
          <span className="text text-1">Find A Table</span>
          <span className="text text-2" aria-hidden="true">
            Find A Table
          </span>
        </a>

        {/*  فتح القائمة */}
        <button
          className="nav-open-btn"
          aria-label="open menu"
          onClick={() => setMenuOpen(true)}
        >
          <span className="line line-1" />
          <span className="line line-2" />
          <span className="line line-3" />
        </button>

        {/* Overlay */}
        {menuOpen && (
          <div className="overlay active" onClick={() => setMenuOpen(false)} />
        )}
      </div>
    </header>
  );
}
